
var win = $(window),
    scrollAreaEl,
    leftFreezeEl,
    leftTableEl,
    rightTableEl,
    myScroll=null;

//动态计算容器最大高度
function adjustHeight() {
    // if(!$('.data-table td').length){
    //     return
    // }
    scrollAreaEl = $('.t_r_content'),
    leftFreezeEl = $('.t_l_freeze'),
    leftTableEl = leftFreezeEl.find('table'),
    rightTableEl = $('.t_r_t table');

    $('.data-table').height('100%');
    var tableHeight = $('.data-table').height();
    tableHeight = tableHeight - $('.t_l > table').height();
    leftFreezeEl.height(tableHeight);
    scrollAreaEl.height(tableHeight);
}
function updatePosition() {
    var a = this.y;
    var b = this.x;
    leftTableEl.css('transform', 'translate(0px, ' + a + 'px) translateZ(0px)');
    rightTableEl.css('transform', 'translate(' + b + 'px, 0px) translateZ(0px)');
}


//调整列宽列高
function initTableSize(rightWidth){
    // if(!$('.data-table td').length){
    //     return
    // }
    //左边冻结列表头第一行的ths
    var leftFreeColThs = $('.t_l table tr:first-child th');
    var leftFreeFirstColTds = $('.t_l_freeze table tr td:first-child');
    //右边冻结列表头第一行的ths
    var rightFreeColThs = $('.t_r_t table tr:first-child th');
    // 右边表格第一列的tds　设置行宽
    var rightTableFirstColTds = $('.t_r_content table tr td:first-child');

    if(rightWidth){
        $('.t_r_t table').css('width',rightWidth);
        $('.t_r_content table').css('width',rightWidth);
        leftTableEl.css('transform', 'none');
        rightTableEl.css('transform', 'none');
    }

    //　左边td高度设置
    for( var a = 0;a< leftFreeFirstColTds.length;a++){
        //左边列高度大于右边高度时
        var leftHeight = $(leftFreeFirstColTds[a]).height(),rightHeight = $(rightTableFirstColTds[a]).height();
        if( leftHeight > rightHeight ){
            $(rightTableFirstColTds[a]).height(leftHeight);
        }else if( leftHeight < rightHeight){//左边列高度小于右边高度时
            $(leftFreeFirstColTds[a]).height(rightHeight)
        }
    }
    //多表头时，设置表头高试
    var rightHeaderTrs = $('.t_r_t').find('tr');
    if( rightHeaderTrs.length > 1){
        var leftHeaderHeight =0;
        for(var i = 0 ; i< rightHeaderTrs.length;i++){
            $(rightHeaderTrs[i]).css('auto');
            leftHeaderHeight += ($(rightHeaderTrs[i]).height() - 0);
        }
        $('.t_l').find('tr th').height(leftHeaderHeight-1);
    }else {
        // 单表头右边表头高度设置
        // leftFreeColThs.css('height','auto');
        for(var b = 0;b< rightFreeColThs.length;b++){
            if(　b === 0 ){ //设置高度时只看第一个
                var leftThHeight = $(leftFreeColThs[0]).height(),rightThHeight = $(rightFreeColThs[0]).height();
                if( leftThHeight > rightThHeight){ //左边的高度大于右边的高度时
                    $(rightFreeColThs[0]).height(leftThHeight)
                }else if(leftThHeight < rightThHeight){//
                    $(leftFreeColThs[0]).height(rightThHeight)
                }
            }
        }
    }
    //设置右边表格的margin-left 的距离
    $('.t_r').css('margin-left',$('.t_l').width()+'px');

    adjustHeight();
    //设置iscroll
    if (myScroll){
        myScroll.destroy();
    }
    myScroll = new IScroll('.t_r_content', {
        scrollX: true,
        scrollY: true,
        probeType: 3
    });

    //阻止默认滚动
    scrollAreaEl.on('touchmove mousewheel', function(e) {
        e.preventDefault();
    });

    //固定上左表头的滚动
    myScroll.on('scroll', updatePosition);
    myScroll.on('scrollEnd', updatePosition);
}

$(function () {
    initTableSize();
    win.on('resize', adjustHeight);
})
